import React, { useState, useEffect } from 'react';

function UserProfile() {
  const [userData, setUserData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Create an AbortController to handle request cancellation
  const controller = new AbortController();

  useEffect(() => {
    // Fetch user data with the AbortController signal
    const fetchUserData = async () => {
      try {
        const response = await fetch('https://api.example.com/user', {
          signal: controller.signal, // Pass the signal to the fetch
        });

        if (!response.ok) {
          throw new Error('Failed to fetch user data');
        }

        const data = await response.json();
        setUserData(data);
      } catch (err) {
        if (err.name !== 'AbortError') {
          // Handle other errors
          setError(err.message);
        }
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();

    // Cleanup function to cancel the request if the component unmounts
    return () => {
      controller.abort();  // Abort the fetch request if component unmounts
    };
  }, []); // Empty dependency array to run this effect only once when the component mounts

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div>
      <h1>{userData.name}</h1>
      <p>{userData.email}</p>
    </div>
  );
}

export default UserProfile;
